text:
{
  "title_novice": "Качественная и количественная интерпретация",
  "summary": [
    {"text": "Интерпретация ГИС бывает качественной и количественной; выбор зависит от сложности коллектора.", "claims": ["c1", "c3"]},
    {"text": "Качественная интерпретация читает признаки типов пород на диаграммах. Для простого межзернового коллектора её достаточно.", "claims": ["c1", "c2"]},
    {"text": "Для сложных коллекторов, подсчёта запасов и разработки нужны числа: пористость, насыщение, проницаемость.", "claims": ["c3", "c4"]}
  ],
  "claims": [
    {"key": "c1", "text": "Первую задачу решают обычно качественной интерпретацией: по признакам основных типов пород на основных диаграммах.", "kind": "observation", "unit_id": "u-090-cdc869", "page": 90, "quote": "Первая из перечисленных задач решается обычно методами качественной интерпретации путем применения признаков основных типов пород на главных диаграммах геофизического комплекса.", "numbers": [], "question": null},
    {"key": "c2", "text": "Для простейшего случая межзерновых коллекторов насыщение, толщину и выделение тоже оценивают качественно.", "kind": "assumption", "unit_id": "u-090-cdc869", "page": 90, "quote": "Выделение, оценка характера насыщения коллекторов и определение их эффективной толщины проводятся для простейшего случая коллекторов с межзерновой пористостью также на основании качественной интерпретации", "numbers": [], "question": null},
    {"key": "c3", "text": "Для более сложных коллекторов нужна количественная интерпретация через коэффициенты и параметр насыщения.", "kind": "observation", "unit_id": "u-090-cdc869", "page": 90, "quote": "а для более сложных — методами количественной интерпретации через оценку коэффициентов пористости, глинистости, нефтегазонасыщения, либо параметра насыщения $P_п$.", "numbers": [], "question": null},
    {"key": "c4", "text": "Промышленная оценка коллекторов опирается на количественные пористость, нефтегазонасыщение и проницаемость, нужные для запасов и разработки.", "kind": "observation", "unit_id": "u-090-cdc869", "page": 90, "quote": "Промышленная оценка коллекторов базируется на количественных определениях пористости, нефтегазонасыщения, проницаемости, используемых при проведении подсчетов запасов и проектировании разработки месторождений.", "numbers": [], "question": null},
    {"key": "c5", "text": "Качественный вывод не годится для подсчёта запасов: нужны количественные определения.", "kind": "inference", "unit_id": "u-090-cdc869", "page": 90, "quote": "Промышленная оценка коллекторов базируется на количественных определениях пористости, нефтегазонасыщения, проницаемости, используемых при проведении подсчетов запасов и проектировании разработки месторождений.", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Разные типы пород дают разный характерный вид кривых на одних и тех же основных диаграммах.", "claims": ["c1"], "hypothesis": false},
    {"text": "Качественная интерпретация сопоставляет вид кривых с признаками основных типов пород и делает вывод по сходству.", "claims": ["c1"], "hypothesis": false},
    {"text": "Для простейшего межзернового коллектора такого визуального сопоставления хватает, чтобы выделить коллектор, оценить насыщение и толщину.", "claims": ["c2"], "hypothesis": false},
    {"text": "Для более сложных коллекторов переходят к расчёту коэффициентов пористости, глинистости и нефтегазонасыщения или параметра насыщения Pн.", "claims": ["c3"], "hypothesis": false},
    {"text": "Коэффициент нефтегазонасыщения — доля пор коллектора, занятая нефтью или газом. Это число, а не вид кривой.", "claims": [], "hypothesis": true},
    {"text": "Для запасов и проекта разработки числа нужны, потому что расчёт идёт по объёмам и долям, а не по виду кривых.", "claims": ["c4", "c5"], "hypothesis": true}
  ],
  "practice": [
    {"text": "Сначала специалист смотрит основные диаграммы и сопоставляет их с признаками основных типов пород.", "claims": ["c1"]},
    {"text": "Для простого межзернового коллектора он выделяет пласт, оценивает насыщение и толщину качественно.", "claims": ["c2"]},
    {"text": "Для сложного коллектора он переходит к количественным коэффициентам или параметру насыщения Pн.", "claims": ["c3"]},
    {"text": "Для подсчёта запасов и проекта разработки берёт количественные пористость, нефтегазонасыщение и проницаемость.", "claims": ["c4"]}
  ],
  "nuances": [
    {"text": "Качественный способ работает для простейших межзерновых коллекторов. Для более сложных он не подходит.", "claims": ["c2", "c3"], "hypothesis": false},
    {"text": "Качественный ответ не годится для подсчёта запасов. Нужны количественные определения.", "claims": ["c5"], "hypothesis": false},
    {"text": "В этом фрагменте книга не объясняет физическую причину различий кривых разных пород. Она только задаёт сам подход.", "claims": [], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Зачем запасам нужны числа", "text": "Подсчёт запасов связывает объём коллектора с долей нефти или газа в нём. Без численной доли этот расчёт не выполнить.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Простейший случай: коллекторы с межзерновой пористостью — оценка качественная.", "claims": ["c2"]},
    {"text": "Более сложные коллекторы — количественная интерпретация через коэффициенты или параметр насыщения Pн.", "claims": ["c3"]},
    {"text": "Промышленная оценка — количественная: пористость, нефтегазонасыщение, проницаемость.", "claims": ["c4"]}
  ],
  "terms_defined": [
    {"term": "качественная интерпретация", "term_en": "qualitative interpretation", "abbr": "", "definition": "Чтение диаграмм по признакам основных типов пород: вид кривых сопоставляют с породой и делают вывод.", "claims": ["c1"]},
    {"term": "количественная интерпретация", "term_en": "quantitative interpretation", "abbr": "", "definition": "Расчёт численных коэффициентов по диаграммам: пористости, глинистости, нефтегазонасыщения или параметра насыщения Pн.", "claims": ["c3"]},
    {"term": "подсчёт запасов", "term_en": "reserves estimation", "abbr": "", "definition": "Расчёт количества нефти или газа в месторождении. Опирается на числа пористости, насыщения и проницаемости.", "claims": ["c4"]},
    {"term": "проектирование разработки", "term_en": "field development design", "abbr": "", "definition": "Планирование того, как извлекать нефть или газ из месторождения. Тоже опирается на количественные оценки.", "claims": ["c4"]}
  ],
  "terms_used": ["литологический разрез", "характер насыщения", "эффективная толщина", "межзерновой коллектор", "коэффициент пористости", "глинистость", "нефтегазонасыщение", "параметр насыщения (Pн)", "проницаемость", "геофизический комплекс", "диаграмма", "продуктивный коллектор", "основные типы пород"],
