  "misconception": {
    "pack_id": null,
    "wrong": "Всё можно решить на глаз по виду кривых. Расчёт коэффициентов не нужен.",
    "right": "Глаз хватает для простейшего межзернового коллектора. Для сложного коллектора и для запасов нужен расчёт коэффициентов.",
    "claims": ["c1", "c2", "c3", "c4"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Кривые основных диаграмм геофизического комплекса, по которым сопоставляют признаки типов пород.", "claims": ["c1"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Качественно: тип породы, характер насыщения и эффективная толщина простейшего межзернового коллектора.", "claims": ["c2"], "hypothesis": false},
      {"text": "Количественно: коэффициенты пористости, глинистости, нефтегазонасыщения или параметр насыщения Pн.", "claims": ["c3"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Для сложных коллекторов качественного чтения недостаточно.", "claims": ["c3"], "hypothesis": false},
      {"text": "Для запасов и разработки нужна проницаемость в виде числа.", "claims": ["c4"], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Качественная интерпретация похожа на визуальный осмотр графика мониторинга. Количественная — на расчёт метрики по формуле.",
    "breaks_where": "Кривая ГИС зависит от породы и бурового раствора, а не только от формы графика. У дашборда такой связи обычно нет."
  },
  "now_nuance": {
    "text": "Сегодня количественный расчёт часто делают программно сразу по многим кривым. Качественный осмотр всё равно остаётся первым шагом."
  },
  "threshold": {
    "is_threshold": true,
    "why": "После различия качественной и количественной интерпретации ясно, какой способ годится для какого коллектора и зачем нужны числа."
  },
